style.css:
@-moz-document domain("youtube.com"), domain("music.youtube.com") {
/* === Accanthis ADF Std Font === */
    @font-face {
        font-family: 'Accanthis ADF Std';
        font-style: normal;
        font-weight: 400;
        src: url("https://cdn.jsdelivr.net/gh/hackclub/fonts/AccanthisADFStd-Regular.woff2") format("woff2"),
             url("https://cdn.jsdelivr.net/gh/hackclub/fonts/AccanthisADFStd-Regular.woff") format("woff");
    }

    /* === Comment Section Text (neon red) === */
    #comments, ytd-comment-renderer, #content-text, #author-text, #author-comment, ytd-comment-thread-renderer {
        font-family: 'Accanthis ADF Std', serif !important;
        color: #FF0000 !important; /* neon red */
        text-shadow: 0 0 2px #FF0000, 0 0 5px #FF0000, 0 0 10px #FF0000 !important;
    }

    /* === Comment timestamps and metadata (neon red) === */
    #published-time-text, #vote-count-middle {
        font-family: 'Accanthis ADF Std', serif !important;
        color: #FF0000 !important; /* neon red */
        text-shadow: 0 0 2px #FF0000, 0 0 5px #FF0000, 0 0 10px #FF0000 !important;
    }

    /* === Comment action icons (like, reply, share) === */
    ytd-comment-action-buttons-renderer, ytd-toggle-button-renderer {
        filter: drop-shadow(0 0 2px #FF0000) drop-shadow(0 0 5px #FF0000) !important; /* neon red glow */
    }

    /* === Sidebar & Navigation icons glow (neon red) === */
    ytd-guide-entry-renderer svg, ytd-mini-guide-entry-renderer svg,
    ytd-topbar-menu-button-renderer svg, #logo-icon-container svg {
        fill: #FF0000 !important; /* neon red */
        filter: drop-shadow(0 0 2px #FF0000) drop-shadow(0 0 5px #FF0000) !important;
    }

    /* === Misc icons (like bell, create video, apps) === */
    ytd-topbar-menu-button-renderer, ytd-notification-topbar-button-renderer, ytd-masthead svg {
        filter: drop-shadow(0 0 2px #FF0000) drop-shadow(0 0 5px #FF0000) !important;
    }

    /* === Video description text (neon green) === */
    #description, ytd-video-secondary-info-renderer #description {
        font-family: 'Accanthis ADF Std', serif !important;
        color: #39FF14 !important; /* neon green */
        text-shadow: 0 0 2px #39FF14, 0 0 5px #39FF14, 0 0 10px #39FF14 !important;
    }

    /* === Video title text (neon green) === */
    #video-title, .title, ytd-video-primary-info-renderer h1 {
        font-family: 'Accanthis ADF Std', serif !important;
        font-weight: 700 !important;
        color: #39FF14 !important; /* neon green */
        text-shadow: 0 0 3px #000, 0 0 5px #39FF14, 0 0 10px #39FF14, 0 0 20px #39FF14 !important;
    }
}
